\label{thm:main_totally_real_uniqueness}
Let $\Omega_{\theta,\mu,E}$ be given by
\eqref{eq:general_layer_domain} and
\begin{equation*}
G(x)=G_0(y)\chi_{\Omega_{\theta,\mu,E}}(x), \quad G_0\in L^1(D),
\end{equation*}
where $x=x_0+y+s\theta$. Assume that
\begin{equation}\label{eq:main_TR_identity_minus}
\int_{\Omega_{\theta,\mu,E}}G(x)e^{-ix\cdot\zeta_\theta(\eta)}\,dx=0,
\quad \eta\in U. 
\end{equation}
Then
\begin{equation*}
G=0, \quad \text{a.e. }\Omega_{\theta,\mu,E}.
\end{equation*}

\label{thm:main_brion_barvinok_uniqueness}
Let $\Omega_{\mathcal B}$ be given by \eqref{eq:broken_layer_domain_main}, and let
\begin{equation*}
G(x)=\sum_{j=1}^N p_j(Y(x))\chi_{P_j}(x),
\end{equation*}
where each $p_j\in\mathbb C[y_1,\ldots,y_{n-1}]$. If either
\begin{equation}\label{eq:BB_minus_identity_main}
\int_{\Omega_{\mathcal B}} G(x)e^{-ix\cdot\zeta_\theta(\eta)}\,dx=0
\quad\text{or}\quad
\int_{\Omega_{\mathcal B}} G(x)e^{ix\cdot\zeta_\theta(\eta)}\,dx=0,
\quad \eta\in U,
\end{equation}
for a nonempty open $U\Subset\theta^\perp\setminus\{0\}$, then
$p_1\equiv\cdots\equiv p_N\equiv0$, and hence $G=0$ a.e. in
$\Omega_{\mathcal B}$.

\label{def:hyperbolic_admissibility}
Let \(\Omega_\sharp\) be either domain in \eqref{eq:Omega_sharp_alternatives}. A pair \((f,c)\) is \emph{hyperbolically admissible} relative to \(\Omega_\sharp\) if the following hold.
\begin{enumerate}
\item \textbf{Sharp truncation and positivity.}
There exist \(f_{\mathrm{in}}\in L^2(\Omega_\sharp)\), \(c_{\mathrm{in}}\in L^\infty(\Omega_\sharp)\), and \(0<c_-\le c_+<\infty\) such that
\begin{equation}\label{eq:main_hyperbolic_common_truncation}
f=f_{\mathrm{in}}\chi_{\Omega_\sharp},\quad
c=1+(c_{\mathrm{in}}-1)\chi_{\Omega_\sharp},\quad
c_-\le c_{\mathrm{in}}\le c_+,\quad \text{a.e. in }\Omega_\sharp.
\end{equation}
Thus \(f\) and \(c-1\) share the same sharp cutoff at \(\partial\Omega_\sharp\),
\begin{equation*}
\operatorname*{ess\,supp}f\cup\operatorname*{ess\,supp}(c-1)
\subset\overline{\Omega}_\sharp,
\end{equation*}
and jumps across \(\partial\Omega_\sharp\) are allowed. Equivalently,
\(q\in L^\infty(\mathbb R^n)\), \(0<q_-\le q\le q_+<\infty\), and
\(q=1\) on \(\mathbb R^n\setminus\overline{\Omega_\sharp}\).

\item \textbf{Transverse quotient structure.}
If \(\Omega_\sharp=\Omega_{\theta,\mu,h}\), then there exists
\(F\in L^1(D)\cap L^2(D)\) such that
\begin{equation}\label{eq:main_hyperbolic_quotient_structure_translated}
\frac{f_{\mathrm{in}}(x)}{c_{\mathrm{in}}^2(x)}=F(y),
\quad\text{a.e. }\Omega_{\theta,\mu,h}.
\end{equation}
Hence \(f/c^2=F(y)\chi_{\Omega_{\theta,\mu,h}}\).

If \(\Omega_\sharp=\Omega_{\mathcal B}=\bigcup_{j=1}^N P_j\), then there exist
transverse polynomials \(F_j\in\mathbb C[y_1,\dots,y_m]\) such that
\begin{equation}\label{eq:main_hyperbolic_quotient_structure_broken}
\frac{f_{\mathrm{in}}(x)}{c_{\mathrm{in}}^2(x)}
=\sum_{j=1}^N F_j(Y(x))\chi_{P_j}(x),\quad\text{a.e. } \Omega_{\mathcal B}.
\end{equation}
Thus \(f/c^2=\sum_{j=1}^N F_j(Y(x))\chi_{P_j}(x)\), compactly supported, with
jumps allowed at the outer boundary and internal polygonal sections.

\item \textbf{Mild forward solution and local decay.}
Let \(u\in C([0,\infty);L^2(\mathbb R^n))\) be the mild solution of
\eqref{eq:main_hyperbolic_forward}. Assume there exist \(C>0\) and a
nonnegative measurable \(\eta\in L^1(0,\infty)\) with \(\eta(t)\to0\) as
\(t\to\infty\), such that
\begin{equation*}
\|u(t,\cdot)\|_{L^2(\Omega_\sharp)}\le C\eta(t)\|f\|_{L^2(\mathbb R^n)},\quad t>0.
\end{equation*}
\end{enumerate}

\label{thm:main_hyperbolic_quotient_uniqueness}
Let \(\Omega_\sharp\) be either an oblique cylinder
\(\Omega_{\theta,\mu,h}\) or a bounded Lipschitz polygonal cylinder
\(\Omega_{\mathcal B}\). Let \((f_\iota,c_\iota)\), \(\iota=1,2\), be two hyperbolically
admissible pairs relative to the same \(\Omega_\sharp\), and assume
\begin{equation*}
\Lambda_{f_1,c_1}^{\Omega_\sharp}(\tau)=\Lambda_{f_2,c_2}^{\Omega_\sharp}(\tau),
\quad\forall\,\tau>0.
\end{equation*}
Then
\begin{equation*}
\frac{f_1}{c_1^2}=\frac{f_2}{c_2^2},\quad\text{a.e. }\mathbb R^n.
\end{equation*}

\label{def:parabolic_admissibility}
A pair \((f,\kappa)\) is \emph{parabolically admissible} relative to
\(\Omega_\sharp\) if the following hold.
\begin{enumerate}
\item \textbf{Sharp truncation and positivity.}
There exist \(f_{\mathrm{in}}\in L^2(\Omega_\sharp)\) and
\(\kappa_{\mathrm{in}}\in L^\infty(\Omega_\sharp)\) with
\(0<\kappa_-\le\kappa_{\mathrm{in}}\le\kappa_+<\infty\) such that
\begin{equation*}
f=f_{\mathrm{in}}\chi_{\Omega_\sharp},\quad \kappa=1+(\kappa_{\mathrm{in}}-1)\chi_{\Omega_\sharp}.
\end{equation*}
Thus \(f\) and \(\kappa-1\) are supported in
\(\overline{\Omega}_\sharp\) and may jump at
\(\partial\Omega_\sharp\). Equivalently, \(q\in L^\infty\)
satisfies \(0<q_-\le q\le q_+<\infty\) and
\(q=1\) outside \(\overline{\Omega}_\sharp\).

\item \textbf{Transverse quotient structure.}
If \(\Omega_\sharp=\Omega_{\theta,\mu,h}\), then
\begin{equation}\label{eq:main_parabolic_quotient_structure_translated}
\frac{f_{\mathrm{in}}(x)}{\kappa_{\mathrm{in}}(x)}=F(y),
\quad F\in L^1(D)\cap L^2(D), \quad \mbox{a.e. }\Omega_{\theta,\mu,h}.
\end{equation}
Hence $f/\kappa=F(y)\chi_{\Omega_{\theta,\mu,h}}$.

If \(\Omega_\sharp=\Omega_{\mathcal B}\), then there exist transverse
polynomials \(F_j\) such that
\begin{equation}\label{eq:main_parabolic_quotient_structure_broken}
\frac{f_{\mathrm{in}}(x)}{\kappa_{\mathrm{in}}(x)}
=\sum_{j=1}^N F_j(Y(x))\chi_{P_j}(x),
\quad\text{a.e. }\Omega_{\mathcal B}.
\end{equation}
Thus
\begin{equation*}
f/\kappa=\sum_{j=1}^N F_j(Y(x))\chi_{P_j}(x), \quad\text{in }\mathbb R^n.
\end{equation*}

\item \textbf{Mild solution, local boundedness and decay.}
Let \(u(t)=e^{-tA_q}f\) be the mild whole-space solution. Assume
\begin{equation*}
\sup_{t\ge0}\|u(t,\cdot)\|_{L^2(\Omega_\sharp)}<\infty,
\quad \|u(t,\cdot)\|_{L^2(\Omega_\sharp)}\to 0,
\quad\text{as }t\to\infty.
\end{equation*}
\end{enumerate}

\label{rem:parabolic_forward_wellposedness}
With \(A_q\) as above, the analytic semigroup \(e^{-tA_q}\) is well defined on
\(L^2(\mathbb R^n)\), and its resolvent gives
\begin{equation*}
U_\lambda=(\lambda+A_q)^{-1}f\in H^2(\mathbb R^n),
\end{equation*}
which is \eqref{eq:main_parabolic_laplace_equation}. Hence the Dirichlet and
weak Neumann traces in \eqref{eq:main_parabolic_laplace_data} lie in the stated
boundary spaces. This formulation uses the \(t>0\) smoothing while allowing a
sharply truncated initial state to lie only in \(L^2\).

\label{thm:main_parabolic_quotient_uniqueness}
Let \(\Omega_\sharp\) be either an oblique cylinder or a polygonal cylinder, and let \((f_\iota,\kappa_\iota)\), \(\iota=1,2\), be parabolically admissible pairs relative to \(\Omega_\sharp\). If
\begin{equation*}
\mathcal P_{f_1,\kappa_1}^{\Omega_\sharp}(\lambda)
=\mathcal P_{f_2,\kappa_2}^{\Omega_\sharp}(\lambda),
\quad\forall\,\lambda>0,
\end{equation*}
then
\begin{equation*}
\frac{f_1}{\kappa_1}=\frac{f_2}{\kappa_2},\quad\text{a.e. }\mathbb R^n.
\end{equation*}

\label{thm:main_finite_time_stability}
Let the two coefficient--initial-state pairs satisfy the support, positivity,
and structural conditions in the corresponding admissibility definition, and
assume
\begin{equation*}
\mathcal M_1^T=\mathcal M_2^T,\quad\text{in }\mathfrak T(\Omega_\sharp)^*.
\end{equation*}
\begin{item}
\item[(1) Oblique cylinder.]
Let \(\Omega_\sharp=\Omega_{\theta,\mu,h}\) and
\begin{equation*}
G(x)=G_0(y)\chi_{\Omega_{\theta,\mu,h}}(x),\quad \widetilde G_0:=G_0\chi_D\in H^S(\mathbb R^{n-1}),\quad\|\widetilde G_0\|_{H^S}\le M,
\end{equation*}
with \(S>0\) and \(M>0\). Then for every \(0\le r<S\),
\begin{equation}\label{eq:main_finite_time_holder}
\|\widetilde G_0\|_{H^r(\mathbb R^{n-1})}
\le C M^{1-\alpha_r}\varepsilon_T^{\alpha_r},
\quad \alpha_r=\frac{S-r}{S+n/2}. 
\end{equation}
Here \(C=C(n,r,S,D,\mu,h)\) is independent of \(G_0,M,T\). For \(r=0\),
\begin{equation*}
\|q_1f_1-q_2f_2\|_{L^2(\Omega_{\theta,\mu,h})}
=h^{1/2}\|G_0\|_{L^2(D)}\le C M^{1-\alpha_0}\varepsilon_T^{\alpha_0},
\quad \alpha_0=\frac{S}{S+n/2},
\end{equation*}
with \(h^{1/2}\) absorbed into \(C\).

\item[(2) Polygonal cylinder.]
Let \(\Omega_\sharp=\Omega_{\mathcal B}\), fix \(d\in\mathbb N_0\), and let
\begin{equation*}
G(x)=\sum_{j=1}^N p_j(Y(x))\chi_{P_j}(x),\quad p_j\in\Pi_d(D),
\end{equation*}
where \(\Pi_d(D)\) is the space of polynomials of total degree at most \(d\)
restricted to \(D\). Set
\begin{equation*}
M_d=\binom{n-1+d}{d},\quad q_d=NM_d.
\end{equation*}
Let \(\Xi=\{(\rho_k,\omega_k):1\le k\le q_d\}\) be any nondegenerate sampling
set from Theorem~\ref{thm:polygonal_finite_dimensional_stability}. Then
\begin{equation}\label{eq:main_finite_time_polygonal}
\|G\|_{L^2(\Omega_{\mathcal B})} \le CK_{\mathcal B,\Xi}\varepsilon_T,
\end{equation}
where
\begin{equation*}
K_{\mathcal B,\Xi}=\left(\sum_{k=1}^{q_d}\|e^{-i(\cdot-x_0)\cdot
\zeta_\theta(\rho_k\omega_k)}\|_{L^2(\Omega_{\mathcal B})}^2
\right)^{1/2}.
\end{equation*}
\end{item}

\label{lem:H_entire_TR}
The function \(H\) in \eqref{eq:H_def_TR} is entire on \(\mathbb C^m\).
Moreover, for every multi-index \(\gamma\in\mathbb N_0^m\),
\begin{equation}\label{eq:H_derivative_formula_TR}
\partial_z^\gamma H(z)=\int_D y^\gamma g_0(y)e^{z\cdot y}\,dy,
\quad z\in\mathbb C^m,
\end{equation}
where \(y^\gamma=y_1^{\gamma_1}\cdots y_m^{\gamma_m}\).

Fix a compact set \(K\Subset\mathbb C^m\). Since \(D\) is bounded, choose
\(R_D>0\) with \(|y|\le R_D\) for \(y\in D\), and set
\(M_K:=\sup_{z\in K}|z|<\infty\). For \(z\in K\), \(y\in D\),
\begin{equation*}
|e^{z\cdot y}|=e^{\operatorname{Re}(z\cdot y)}\le e^{|z||y|}\le e^{M_KR_D}.
\end{equation*}
Hence \(|g_0(y)e^{z\cdot y}|\le e^{M_KR_D}|g_0(y)|\), which is integrable on
\(D\). Thus \(H\) is well defined and locally bounded.

To justify differentiation under the integral sign, fix \(z\in\mathbb C^m\)
and a coordinate vector \(e_j\). For small \(h\),
\begin{equation*}
\frac{e^{(z+he_j)\cdot y}-e^{z\cdot y}}{h}=y_j e^{z\cdot y}\int_0^1 e^{thy_j}\,dt.
\end{equation*}
For \(z,z+he_j\in K\) and \(|h|\le1\), this is bounded by $R_De^{(M_K+1)R_D}|g_0(y)|$,
which is integrable. Dominated convergence gives
\begin{equation*}
\partial_{z_j}H(z)=\int_D y_jg_0(y)e^{z\cdot y}\,dy.
\end{equation*}
Repeating the argument yields
\eqref{eq:H_derivative_formula_TR}.

Finally, for fixed \(z_0\in\mathbb C^m\),
\begin{equation*}
e^{z\cdot y}=e^{z_0\cdot y}\sum_{\gamma\in\mathbb N_0^m}
\frac{y^\gamma(z-z_0)^\gamma}{\gamma!}.
\end{equation*}
On a small ball about \(z_0\), the series is dominated by \(C|g_0(y)|\).
Termwise integration gives a convergent power series with coefficients
\(\partial_z^\gamma H(z_0)/\gamma!\). Hence \(H\) is holomorphic at every
point of \(\mathbb C^m\), and therefore entire.

\label{lem:MU_totally_real_TR}
The set \(M_U\) defined in \eqref{eq:MU_def_TR} is an embedded real-analytic,
maximally totally real submanifold of \(\mathbb C^{n-1}\).

We show that \(\Phi\) is a real-analytic embedding and that \(M_U\) is totally real.

Since \(U\Subset\mathbb R^{n-1}\setminus\{0\}\), the map \(\eta\mapsto|\eta|\) is
real analytic, so \(\Phi\) is real analytic. Moreover,
\begin{equation*}
\operatorname{Re}\Phi(\eta)=|\eta|\mu,
\quad \operatorname{Im}\Phi(\eta)=-\eta.
\end{equation*}
Thus \(\eta=-\operatorname{Im}z\) for \(z\in M_U\), so \(\Phi\) is injective
with real-analytic inverse \(z\mapsto-\operatorname{Im}z\).

For \(a\in\mathbb R^{n-1}\),
\begin{equation*}
d\Phi_\eta(a)=\mu\frac{\eta\cdot a}{|\eta|}-ia.
\end{equation*}
If \(d\Phi_\eta(a)=0\), then taking imaginary parts gives \(a=0\). Hence
\(\Phi\) is an immersion, and therefore an embedding. Thus \(M_U\) is an
\(m\)-dimensional real-analytic submanifold of \(\mathbb C^{n-1}\).

It remains to prove total reality. Fix \(\eta\in U\), set
\(e=\eta/|\eta|\), and suppose
\begin{equation*}
v\in T_{\Phi(\eta)}M_U\cap iT_{\Phi(\eta)}M_U.
\end{equation*}
Then for some \(a,b\in\mathbb R^{n-1}\),
\begin{equation*}
v=\mu(e\cdot a)-ia,\quad v=i\{\mu(e\cdot b)-ib\}=b+i\mu(e\cdot b).
\end{equation*}
Comparing real and imaginary parts,
\begin{equation*}
b=\mu(e\cdot a),\quad -a=\mu(e\cdot b).
\end{equation*}
Substituting the first identity into the second gives
\begin{equation*}
a=-\mu(e\cdot\mu)(e\cdot a).
\end{equation*}
Taking the scalar product with \(e\),
\begin{equation*}
\bigl(1+(e\cdot\mu)^2\bigr)(e\cdot a)=0.
\end{equation*}
Since the coefficient is positive, \(e\cdot a=0\), hence \(b=0\) and
\(a=0\). Therefore \(v=0\), so
\begin{equation*}
T_{\Phi(\eta)}M_U\cap iT_{\Phi(\eta)}M_U=\{0\}.
\end{equation*}
Thus \(M_U\) is maximally totally real.

\label{lem:local_graph_TR}
Let \(M\subset\mathbb C^{n-1}\) be a real-analytic maximally totally real
submanifold and \(p\in M\). After a translation and a complex-linear change
of coordinates, \(M\) is locally the graph
\begin{equation}\label{eq:local_graph_form}
M=\{x+i\varphi(x):x\in V\subset\mathbb R^m\},
\end{equation}
where \(V\) is a neighborhood of \(0\) and \(\varphi:V\to\mathbb R^{n-1}\) is
real analytic with \(\varphi(0)=0\) and \(D\varphi(0)=0\).

Assume \eqref{eq:main_TR_identity_minus}. By the reduction in
Subsection~\ref{subsec:FL_reduction_TR}, the Fourier--Laplace transform \(H\)
from \eqref{eq:H_def_TR} satisfies
\begin{equation*}
H|_{M_U}=0,\quad M_U=\{|\eta|\mu-i\eta:\eta\in U\}.
\end{equation*}
By Lemma~\ref{lem:H_entire_TR}, \(H\) is entire on \(\mathbb C^{n-1}\), and by
Lemma~\ref{lem:MU_totally_real_TR}, \(M_U\) is a real-analytic maximally
totally real submanifold of \(\mathbb C^{n-1}\). Since \(U\) is open and nonempty,
\(M_U\) is a nonempty relatively open subset of this submanifold. Hence
Lemma~\ref{lem:holomorphic_uniqueness_TR}, with \(O=\mathbb C^{n-1}\), gives
\begin{equation}
H\equiv0, \quad\text{in }\mathbb C^{n-1}.
\label{eq:H_identically_zero}
\end{equation}

Evaluating on the imaginary axis, for every \(\lambda\in\mathbb R^{n-1}\),
\begin{equation*}
0=H(-i\lambda)=\int_D g_0(y)e^{-i\lambda\cdot y}\,dy.
\end{equation*}
Let \(\widetilde g_0\) be the zero extension of \(g_0\) to \(\mathbb R^{n-1}\).
Since \(g_0\in L^1(D)\) and \(D\) is bounded, \(\widetilde g_0\in L^1(\mathbb R^{n-1})\).
Thus
\begin{equation*}
\widehat{\widetilde g_0}(\lambda)=\int_{\mathbb R^m}\widetilde g_0(y)e^{-i\lambda\cdot y}\,dy=0, \quad \lambda\in\mathbb R^{n-1}.
\end{equation*}
By injectivity of the Fourier transform on \(L^1(\mathbb R^{n-1})\),
\(\widetilde g_0=0\) a.e.; hence \(g_0=0\) a.e. in \(D\). By the structural
assumption \eqref{eq:g_codimension_one_structure_TR},
\begin{equation*}
g(x)=g_0(y)\chi_{\Omega_{\theta,\mu,E}}(x)=0, \quad  \mbox{a.e.~}\Omega_{\theta,\mu,E}.
\end{equation*}
For the sign-reversed identity, assume
\begin{equation*}
\int_{\Omega_{\theta,\mu,E}}g(x)e^{ix\cdot\zeta_\theta(\eta)}\,dx=0,
\quad \eta\in U.
\end{equation*}
Using (\ref{eq:phase_factorization_general}), Fubini's theorem gives
\begin{equation*}
B_E^-(|\eta|)
\int_D g_0(y)\exp\bigl[(-|\eta|\mu+i\eta)\cdot y\bigr]\,dy=0,
\end{equation*}
where $B_E^-(\rho):=\int_E e^{-\rho r}\,dr$. Since \(B_E^-(\rho)>0\) for \(\rho>0\),
$H(i\eta-|\eta|\mu)=0$, $\eta\in U$. But
\begin{equation*}
\Phi_+(\eta):=i\eta-|\eta|\mu=-\Phi(\eta),
\end{equation*}
and multiplication by \(-1\) preserves embeddedness and the maximally totally
real property. Hence \(\Phi_+(U)\) is again a real-analytic maximally totally
real submanifold. The same holomorphic uniqueness and Fourier transform
arguments yield \(H\equiv0\) and \(g=0\) a.e. This proves both assertions.

\label{lem:weighted_BB_vertex_expansion}
Let \(D\subset\mathbb R^{n-1}\) be a compact simple convex polytope with nonempty
interior, and let \(p\in\mathbb C[y_1,\ldots,y_{n-1}]\). For each vertex
\(v\in V(D)\), let \(u_{v,1},\ldots,u_{v,n-1}\) be the inward edge directions
generating the tangent cone
\begin{equation*}
C_v=\left\{v+\sum_{k=1}^{n-1} s_ku_{v,k}:s_k\ge0\right\}.
\end{equation*}
Then there exist rational functions \(R_{D,p,v}(z)\), \(v\in V(D)\), such that
\begin{equation}\label{eq:weighted_BB_expansion}
\int_D p(y)e^{z\cdot y}\,dy=\sum_{v\in V(D)}e^{z\cdot v}R_{D,p,v}(z),
\end{equation}
as a meromorphic identity in \(z\in\mathbb C^{n-1}\). If
\begin{equation*}
p\left(v+\sum_{k=1}^{n-1} s_ku_{v,k}\right)
=\sum_{\alpha\in\mathbb N_0^{n-1}}c_\alpha^{(v)}s^\alpha,
\end{equation*}
then
\begin{equation}\label{eq:explicit_R_Dpv}
R_{D,p,v}(z)=|\det(u_{v,1},\ldots,u_{v,n-1})|
\sum_\alpha c_\alpha^{(v)}\frac{(-1)^{|\alpha|+n-1}\alpha!}
{\prod_{k=1}^{n-1}(z\cdot u_{v,k})^{\alpha_k+1}}.
\end{equation}
Moreover, if \(p\not\equiv0\), then
\begin{equation*}
R_{D,p,v}\not\equiv0, \quad \forall \,v\in V(D).
\end{equation*}

\noindent {Step 1.} Set
\begin{equation*}
H_{D,p}(z):=\int_D p(y)e^{z\cdot y}\,dy,\quad z\in\mathbb C^{n-1}.
\end{equation*}
Since \(D\) is compact and \(p\) is polynomial, the integral converges
absolutely for every \(z\in\mathbb C^{n-1}\). Differentiation under the integral
sign gives
\begin{equation*}
\partial_z^\alpha H_{D,p}(z)=\int_D y^\alpha p(y)e^{z\cdot y}\,dy.
\end{equation*}
Hence \(H_{D,p}\) is entire. The Brion--Barvinok expansion represents it as a
sum of meromorphic vertex terms whose poles cancel in the total sum.

\noindent {Step 2.}
Fix a vertex \(v\in V(D)\). Since \(D\) is simple, the tangent cone at \(v\) is generated by \(m\) linearly independent inward edge directions \(u_{v,1},\ldots,u_{v,n-1}\):
\begin{equation*}
C_v=\left\{v+\sum_{k=1}^{n-1} s_k u_{v,k}:s_k\ge0\right\}.
\end{equation*}
In the region $\operatorname{Re}(z\cdot u_{v,k})<0$, $k=1,\cdots,n-1$, the cone integral \(\int_{C_v}p(y)e^{z\cdot y}\,dy\) converges absolutely. Using $
y=v+\sum_{k=1}^{n-1} s_k u_{v,k}$, $s_k\ge0$, we get
\begin{equation}\label{eq:cone_integral_computation_clear}
\int_{C_v}p(y)e^{z\cdot y}\,dy=e^{z\cdot v}|\det(u_{v,1},\cdots,u_{v,m})| \int_{\mathbb R_+^{n-1}}p\left(v+\sum_{k=1}^{n-1} s_k u_{v,k}\right)e^{\sum_{k=1}^{n-1} s_k z\cdot u_{v,k}}\,ds.
\end{equation}
Expand
\begin{equation*}
p\left(v+\sum_{k=1}^{n-1} s_k u_{v,k}\right)
=\sum_{\alpha\in\mathbb N_0^{n-1}}c_\alpha^{(v)}s^\alpha .
\end{equation*}
Substituting this into \eqref{eq:cone_integral_computation_clear} and using Fubini's theorem,
\begin{equation*}
\int_{C_v}p(y)e^{z\cdot y}\,dy=e^{z\cdot v}|\det(u_{v,1},\ldots,u_{v,n-1})|
\sum_\alpha c_\alpha^{(v)}\prod_{k=1}^{n-1}\int_0^\infty 
s_k^{\alpha_k}e^{s_k z\cdot u_{v,k}}\,ds_k .
\end{equation*}
It follows from 
\begin{equation*}
\int_0^\infty s^\ell e^{as}\,ds=\frac{(-1)^{\ell+1}\ell!}{a^{\ell+1}},\quad \operatorname{Re}a<0, \quad  \ell \geq 1,
\end{equation*}
that in the convergence region,
\begin{equation*}
\int_{C_v}p(y)e^{z\cdot y}\,dy=e^{z\cdot v}R_{D,p,v}(z),
\end{equation*}
where
\begin{equation*}
R_{D,p,v}(z)=|\det(u_{v,1},\ldots,u_{v,n-1})|\sum_\alpha c_\alpha^{(v)}
\frac{(-1)^{|\alpha|+n-1}\alpha!} {\prod_{k=1}^{n-1}(z\cdot u_{v,k})^{\alpha_k+1}} .
\end{equation*}
The right-hand side is rational in \(z\), so it gives the meromorphic continuation
\begin{equation*}
\int_{C_v}^{\mathrm{mer}}p(y)e^{z\cdot y}\,dy=e^{z\cdot v}R_{D,p,v}(z).
\end{equation*}

\noindent {Step 3.}
For a tangent cone \(C_v\), the integral $\int_{C_v} p(y)e^{z\cdot y}\,dy$
converges absolutely when $\operatorname{Re}(z\cdot u_{v,k})<0$, $k=1,\cdots,n-1$.
Let \(\int_{C_v}^{\mathrm{mer}}\) denote its meromorphic continuation; in the
convergence region it agrees with the ordinary integral, and elsewhere it is
defined by the rational expression from Step 2.

Write $p(y)=\sum_\beta a_\beta y^\beta$ and $p(\partial_z):=\sum_\beta a_\beta \partial_z^\beta$. Barvinok's unweighted formula \cite[Theorem~2.6]{barvinok1993computing} gives
\begin{equation}\label{eq:unweighted_BB_meromorphic_identity}
\int_D e^{z\cdot y}\,dy=\sum_{v\in V(D)}\int_{C_v}^{\mathrm{mer}} e^{z\cdot y}\,dy.
\end{equation}
Since \(D\) is compact, differentiating under the integral sign yields
\begin{equation*}
p(\partial_z)\int_D e^{z\cdot y}\,dy=\int_D p(y)e^{z\cdot y}\,dy.
\end{equation*}
For fixed \(v\), the same holds in the convergence region, so
\begin{equation*}
p(\partial_z)\int_{C_v} e^{z\cdot y}\,dy=\int_{C_v} p(y)e^{z\cdot y}\,dy.
\end{equation*}
Both sides continue meromorphically, hence
\begin{equation*}
p(\partial_z)\int_{C_v}^{\mathrm{mer}} e^{z\cdot y}\,dy
=\int_{C_v}^{\mathrm{mer}} p(y)e^{z\cdot y}\,dy.
\end{equation*}
Applying \(p(\partial_z)\) to \eqref{eq:unweighted_BB_meromorphic_identity}
and using this termwise gives
\begin{equation*}
\int_D p(y)e^{z\cdot y}\,dy=\sum_{v\in V(D)}
\int_{C_v}^{\mathrm{mer}} p(y)e^{z\cdot y}\,dy.
\end{equation*}
By Step 2,
\begin{equation*}
\int_D p(y)e^{z\cdot y}\,dy=\sum_{v\in V(D)} e^{z\cdot v}R_{D,p,v}(z),
\end{equation*}
which is \eqref{eq:weighted_BB_expansion}.

The terms \(e^{z\cdot v}R_{D,p,v}(z)\) may have poles on \(z\cdot u_{v,k}=0\), but the full sum is entire, since it equals \(z\mapsto \int_D p(y)e^{z\cdot y}\,dy\). Thus the identity is meromorphic and all poles cancel in the sum.

\noindent {Step 4.}
It remains to prove that if \(p\not\equiv0\), then $R_{D,p,v}\not\equiv0$,
$\forall \,v\in V(D)$. Suppose \(R_{D,p,v}\equiv0\) for some vertex \(v\). Set
$X_k:=z\cdot u_{v,k}$, $k=1,\cdots,n-1$. Since \(u_{v,1},\cdots,u_{v,n-1}\) are linearly independent, \(X_1,\cdots,X_{n-1}\) are linear coordinates on \(\mathbb C^{n-1}\). Then
\begin{equation*}
0\equiv\sum_\alpha c_\alpha^{(v)} \frac{(-1)^{|\alpha|+n-1}\alpha!}
{X_1^{\alpha_1+1}\cdots X_{n-1}^{\alpha_{n-1}+1}}.
\end{equation*}
Choose \(M\) larger than every component of every multi-index \(\alpha\) in the
finite sum, and multiply by \(X_1^{M+1}\cdots X_{n-1}^{M+1}\). This gives the
polynomial identity
\begin{equation*}
0\equiv\sum_\alpha c_\alpha^{(v)}(-1)^{|\alpha|+n-1}\alpha!
X_1^{M-\alpha_1}\cdots X_{n-1}^{M-\alpha_{n-1}}.
\end{equation*}
By linear independence of monomials, $c_\alpha^{(v)}=0$, $\forall \,\alpha$.
Hence
\begin{equation*}
p\left(v+\sum_{k=1}^{n-1} s_k u_{v,k}\right)\equiv 0,
\end{equation*}
as a polynomial in \(s\). Since $s\longmapsto v+\sum_{k=1}^{n-1} s_k u_{v,k}$ is an invertible affine change of coordinates, this implies \(p\equiv0\), contradicting the assumption. Therefore \(R_{D,p,v}\not\equiv0\) for every vertex \(v\).

\label{lem:homogeneous_polynomial_physical_ray}
Let \(P\) be a nonzero homogeneous polynomial on \(\mathbb C^{n-1}\), let
\(\gamma\in\mathbb R^{n-1}\), \(\sigma\in\{1,-1\}\), and let
\(\mathcal O\subset\mathbb S^{n-2}\) be nonempty and relatively open. Then
\(P(\gamma-i\sigma\omega)\) is not identically zero on \(\mathcal O\). Hence
\begin{equation*}
\{\omega\in\mathcal O:P(\gamma-i\sigma\omega)=0\},
\end{equation*}
has empty interior in \(\mathcal O\).

\label{lem:vertex_coefficient_asymptotics}
Let \(D\), \(p\), \(v\), and \(R_{D,p,v}\) be as in
Lemma~\ref{lem:weighted_BB_vertex_expansion}, and assume \(p\not\equiv0\).
Write
\begin{equation*}
p\left(v+\sum_{k=1}^{n-1} s_k u_{v,k}\right)=\sum_{\alpha} c_\alpha^{(v)} s^\alpha,
\end{equation*}
and set $\kappa_{p,v}:=\min\{|\alpha|:c_\alpha^{(v)}\ne0\}$. Then
\begin{equation}\label{eq:R_vertex_asymptotic}
R_{D,p,v}(\rho\lambda)=\rho^{-(n-1)-\kappa_{p,v}}
R_{D,p,v}^{[\kappa]}(\lambda)+O(\rho^{-(n-1)-\kappa_{p,v}-1}),\quad \mbox{as~} \rho\to+\infty,
\end{equation}
uniformly on compact subsets of $\left\{\lambda:\prod_{k=1}^{n-1}(\lambda\cdot u_{v,k})\ne0\right\}$. Here
\begin{equation}\label{eq:R_leading_homogeneous_rational}
R_{D,p,v}^{[\kappa]}(\lambda)
=|\det(u_{v,1},\ldots,u_{v,n-1})|\sum_{|\alpha|=\kappa_{p,v}}
c_\alpha^{(v)}\frac{(-1)^{\kappa_{p,v}+n-1}\alpha!}
{\prod_{k=1}^{n-1}(\lambda\cdot u_{v,k})^{\alpha_k+1}},
\end{equation}
is a nonzero homogeneous rational function of degree
\(-(n-1)-\kappa_{p,v}\).

\label{lem:finite_family_generic_ray}
Let \(\mathcal O\subset\mathbb S^{n-2}\) be nonempty and relatively open, and let $\{(\gamma_\ell,\sigma_\ell,D_\ell,p_\ell,v_\ell)\}_{\ell=1}^M$ be a finite family with $\gamma_\ell\in\mathbb R^{n-1}$, $\sigma_\ell\in\{\pm1\}$, \(D_\ell\) a compact simple convex polytope, \(p_\ell\not\equiv0\), and \(v_\ell\in V(D_\ell)\). Then there exists \(\omega\in\mathcal O\) such that,
for every \(\ell\),
\begin{equation*}
(\gamma_\ell-i\sigma_\ell\omega)\cdot u_{\ell,v_\ell,k}\ne0,
\quad k=1,\cdots,n-1, \quad R_{D_\ell,p_\ell,v_\ell}^{[\kappa]}
(\gamma_\ell-i\sigma_\ell\omega)\ne0,
\end{equation*}
and
\begin{equation*}
\omega\cdot(v-w)\ne 0, \quad  \forall \,   v\ne w\in V(D_\ell).
\end{equation*}
Consequently, for this \(\omega\), each function $\rho\mapsto
R_{D_\ell,p_\ell,v_\ell}
\bigl(\rho(\gamma_\ell-i\sigma_\ell\omega)\bigr)$ 
has no poles for all sufficiently large \(\rho\) and grows polynomially in
\(\rho\). In fact, for each \(\ell\), there exist constants
\(c_\ell,C_\ell>0\) and \(\rho_\ell>0\) such that
\begin{equation*}
c_\ell\rho^{-(n-1)-\kappa_\ell} \le \left|R_{D_\ell,p_\ell,v_\ell}
\bigl(\rho(\gamma_\ell-i\sigma_\ell\omega)\bigr)\right|
\le C_\ell\rho^{-(n-1)-\kappa_\ell},\quad \rho\ge\rho_\ell,
\end{equation*}
where \(\kappa_\ell=\kappa_{p_\ell,v_\ell}\).

\label{lem:dominant_oscillatory_laurent_separation}
Let \(\beta_1,\cdots,\beta_M\in\mathbb R\) be pairwise distinct, and let
\(r_1,\cdots,r_M\) be nonzero finite Laurent polynomials in \(\rho\). If
\(\delta>0\), then
\begin{equation}
\label{eq:oscillatory_laurent_exponential_smallness}
\left|\sum_{k=1}^M e^{-i\rho\beta_k}r_k(\rho)\right|
\leq C e^{-\delta\rho}\rho^A,
\end{equation}
cannot hold for all sufficiently large \(\rho\).

Let \(d\) be the largest power of \(\rho\) occurring in any \(r_k\), and let
\(c_k\) be the coefficient of \(\rho^d\) in \(r_k\), with \(c_k=0\) if that
power is absent. At least one \(c_k\) is nonzero. Dividing
\eqref{eq:oscillatory_laurent_exponential_smallness} by \(\rho^d\) gives
\begin{equation*}
\sum_{k=1}^M c_k e^{-i\rho\beta_k}=o(1), \quad\text{as }\rho\to+\infty,
\end{equation*}
since \(r_k(\rho)/\rho^d=c_k+o(1)\). On the other hand, the frequencies
\(\beta_k\) are pairwise distinct, so
\begin{equation*}
\lim_{T\to+\infty}\frac1T\int_0^T\left|\sum_{k=1}^M c_k e^{-i\rho\beta_k}
\right|^2\,d\rho=\sum_{k=1}^M |c_k|^2>0.
\end{equation*}
But the integrand tends to \(0\) and is bounded, so its Ces\`aro mean must also
tend to \(0\). This contradiction proves the claim.

Assume that the first equation of \eqref{eq:BB_minus_identity_main} holds. By
\eqref{eq:BB_reduced_minus}, the reduced identity is
\begin{equation*}
\sum_{j=1}^N\frac{e^{-ir_j\cdot\zeta_\theta(\eta)}
-e^{-ir_{j-1}\cdot\zeta_\theta(\eta)}}{\lambda_j(\eta)}H_j(-i\eta)=0.
\end{equation*}
By the choice of \(\mathcal C_U\), the set \(U\cap\mathcal C_U\) is a nonempty
open subset of \(\mathcal C_U\). Since the left-hand side is real analytic on
\(\theta^\perp\setminus\{0\}\) and vanishes on \(U\cap\mathcal C_U\), analytic
continuation on the connected set \(\mathcal C_U\) shows that it vanishes on all
of \(\mathcal C_U\).

For each \(j\), Lemma~\ref{lem:weighted_BB_vertex_expansion} gives
\begin{equation*}
H_j(z)=\sum_{v\in V(D)}e^{z\cdot v}R_{j,v}(z),\quad R_{j,v}:=R_{D,p_j,v}.
\end{equation*}
Along a ray \(\eta=\rho\omega\), set $a_j(\omega):=1-i\gamma_j\cdot\omega$.
Since \(\operatorname{Re}a_j(\omega)=1\), we have \(a_j(\omega)\ne0\).
Substituting the vertex expansion into the reduced identity gives, away from
the polar hyperplanes,
\begin{equation}\label{eq:BB_vertex_identity_minus}
\sum_{j=1}^N\sum_{v\in V(D)}\frac{e^{\rho U_j(v;\omega)}
-e^{\rho L_j(v;\omega)}}{\rho a_j(\omega)}R_{j,v}(-i\rho\omega)=0.
\end{equation}
This identity is well-defined along every ray for which the finitely many
restricted denominators are not identically zero; after excluding their
finitely many positive zeros in \(\rho\), it holds for all sufficiently large
\(\rho\). It follows from the entire reduced identity, the right-hand side
being only a meromorphic representation of it.

Let $J:=\{j:p_j\not\equiv 0\}$. We prove \(J=\varnothing\). 

Suppose \(J\ne\varnothing\), and set $j_*:=\max J$. The upper endpoint of this segment has height \(t_{j_*}\), while every other nonzero endpoint contribution has height at most \(t_{j_*-1}\). Thus the exponential gap is
\begin{equation*}
\delta:=t_{j_*}-t_{j_*-1}=h_{j_*}>0.
\end{equation*}
Apply Lemma~\ref{lem:finite_family_generic_ray} to the family
\begin{equation*}
(0,1,D,p_j,v),\quad j\in J,\quad v\in V(D),
\end{equation*}
with \(\mathcal O=\mathcal O_U\). We obtain \(\omega\in\mathcal O_U\) such that all relevant vertex coefficients are nonzero finite Laurent polynomials along
$\eta=\rho\omega$, $z=-i\rho\omega$, and such that the numbers \(\omega\cdot v\), \(v\in V(D)\), are pairwise distinct.

The upper endpoint contribution of the \(j_*\)-th segment in \eqref{eq:BB_vertex_identity_minus} is
\begin{equation*}
e^{\rho t_{j_*}}
\sum_{v\in V(D)}
e^{-i\rho\omega\cdot(b_{j_*}+v)}
\frac{R_{j_*,v}(-i\rho\omega)}
{\rho a_{j_*}(\omega)}.
\end{equation*}
Each Laurent polynomial here is nonzero, and the frequencies
\(\omega\cdot(b_{j_*}+v)\) are pairwise distinct. All remaining terms in
\eqref{eq:BB_vertex_identity_minus} are bounded by $C e^{\rho(t_{j_*}-\delta)}\rho^A$
for suitable \(A,C>0\). Dividing the identity by \(e^{\rho t_{j_*}}\), we contradict
Lemma~\ref{lem:dominant_oscillatory_laurent_separation}. Hence \(J=\varnothing\), and therefore $p_1=\cdots=p_N=0$. This proves \(G=0\) a.e. in \(\Omega_{\mathcal B}\) for the negative phase.

For the sign-reversed case, assume that the second equation of \eqref{eq:BB_minus_identity_main} holds. The reduced identity is \eqref{eq:BB_reduced_plus}. Away from the polar hyperplanes, the vertex expansion gives
\begin{equation*}
\sum_{j=1}^N\sum_{v\in V(D)}\frac{e^{-\rho L_j(v;\omega)}
-e^{-\rho U_j(v;\omega)}}{\rho a_j(\omega)}R_{j,v}(i\rho\omega)=0.
\end{equation*}
Suppose \(J\ne\varnothing\), choose \(j_*:=\min J\). The lower endpoint of this segment has exponent \(-t_{j_*-1}\), while every other nonzero endpoint contribution has exponent at most \(-t_{j_*}\); the gap is again \(h_{j_*}>0\). Apply Lemma~\ref{lem:finite_family_generic_ray} to
\begin{equation*}
(0,-1,D,p_j,v),\quad j\in J,\quad v\in V(D),
\end{equation*}
and choose \(\omega\in\mathcal O_U\) with pairwise distinct vertex projections. The dominant lower-endpoint cluster is
\begin{equation*}
e^{-\rho t_{j_*-1}}\sum_{v\in V(D)}e^{i\rho\omega\cdot(b_{j_*-1}+v)}
\frac{R_{j_*,v}(i\rho\omega)}{\rho a_{j_*}(\omega)}.
\end{equation*}
After division by \(e^{-\rho t_{j_*-1}}\), all other terms are exponentially smaller.
Lemma~\ref{lem:dominant_oscillatory_laurent_separation}, now with frequencies
\(-\omega\cdot(b_{j_*-1}+v)\), gives a contradiction. Hence \(J=\varnothing\), and all \(p_j\) vanish identically also for the positive phase.

\label{thm:polygonal_finite_dimensional_stability}
Fix a nonempty open \(U\Subset\theta^\perp\setminus\{0\}\). Let
\(p_j\in\Pi_d(D)\), \(j=1,\cdots,N\). There exist \(q_d\) sampling pairs
\(\Xi\) as in \eqref{eq:geometric_sampling_set} such that
\(\Delta_{\mathcal B,d,\Xi}^{\mathrm{geo}}>0\). For any such \(\Xi\), set
\begin{equation*}
\rho^*:=\max_{1\le k\le q_d}\rho_k,\quad 
L_\theta:=T_N=\sum_{j=1}^N\ell_j\cos\beta_j,\quad h^*:=\max_j(\ell_j\cos\beta_j),
\quad B_{\mathcal B,\Xi}^{\mathrm{geo}}
:=h^*|D|e^{\rho^*L_\theta}.
\end{equation*}
Then
\begin{equation}\label{eq:sampled_polygonal_stability}
\|G\|_{L^2(\Omega_{\mathcal B})}\le C_{\mathcal B,d,\Xi}^{\mathrm{geo}}
\left(\sum_{k=1}^{q_d}|(\mathcal T_{\mathcal B}G)(\rho_k\omega_k)|^2
\right)^{1/2},
\end{equation}
where
\begin{equation}\label{eq:explicit_determinant_stability_bound}
C_{\mathcal B,d,\Xi}^{\mathrm{geo}}
:=\sqrt{h^*|D|M_d}\,\frac{q_d^{(q_d+1)/2}\left(B_{\mathcal B,\Xi}^{\mathrm{geo}}\right)^{q_d-1}}{\Delta_{\mathcal B,d,\Xi}^{\mathrm{geo}}}.
\end{equation}
In particular,
\begin{equation*}
\|G\|_{L^2(\Omega_{\mathcal B})}\le \sqrt{q_d}\,
C_{\mathcal B,d,\Xi}^{\mathrm{geo}}\|\mathcal T_{\mathcal B}G\|_{L^\infty(U)}.
\end{equation*}
The same bounds hold for differences of two degree-\(d\) densities, giving a
deterministic noise-amplification bound.

By Theorem~\ref{thm:main_brion_barvinok_uniqueness}, the functions
\begin{equation*}
A_{j,\alpha}^{\mathrm{geo}}(\rho,\omega),\quad
1\le j\le N,\quad \alpha\in\mathcal I_d,
\end{equation*}
are linearly independent on
\(X=\{(\rho,\omega):\rho\omega\in U\}\). Hence we may choose
\(x_k=(\rho_k,\omega_k)\in X\), \(1\le k\le q_d\), such that the evaluation
matrix \(\mathbf A_{\mathcal B,d,\Xi}^{\mathrm{geo}}\) is invertible: otherwise
all evaluation rows would lie in a proper subspace, giving a nontrivial linear
combination vanishing on \(X\). Thus
\(\Delta_{\mathcal B,d,\Xi}^{\mathrm{geo}}>0\).

Let \(\mathbf c=(c_{j,\alpha})\). By \eqref{eq:scaled_monomial_bound},
\begin{equation*}
|p_j(y)|\le \sqrt{M_d} 
\left(\sum_{\alpha\in\mathcal I_d}|c_{j,\alpha}|^2\right)^{1/2}.
\end{equation*}
Since the sweep map has unit Jacobian,
\begin{equation*}
\|G\|_{L^2(\Omega_{\mathcal B})}^2
=\sum_{j=1}^N h_j\int_D |p_j(y)|^2\,dy\le h^*|D|M_d
\sum_{j=1}^N\sum_{\alpha\in\mathcal I_d}|c_{j,\alpha}|^2.
\end{equation*}
Therefore
\begin{equation}\label{eq:geometric_coefficient_to_density_bound}
\|G\|_{L^2(\Omega_{\mathcal B})}
\le \sqrt{h^*|D|M_d}\,\|\mathbf c\|_{\ell^2}.
\end{equation}

For an entry of \(\mathbf A_{\mathcal B,d,\Xi}^{\mathrm{geo}}\), the
longitudinal factor in \eqref{eq:stability_column_length_angle_form} equals
\begin{equation*}
e^{\rho T_{j-1}-i\rho\omega\cdot B_{j-1}}\int_0^{\ell_j\cos\beta_j}
e^{\tau\rho(1-i\tan\beta_j\widehat\gamma_j\cdot\omega)}\,d\tau.
\end{equation*}
Hence
\begin{equation*}
|A_{j,\alpha}^{\mathrm{geo}}(\rho_k,\omega_k)|
\le \ell_j\cos\beta_j\,|D|e^{\rho_kT_j}\le B_{\mathcal B,\Xi}^{\mathrm{geo}}.
\end{equation*}
By Hadamard's inequality, every \((q_d-1)\times(q_d-1)\) cofactor of
\(\mathbf A_{\mathcal B,d,\Xi}^{\mathrm{geo}}\) is bounded by
$q_d^{(q_d-1)/2}\bigl(B_{\mathcal B,\Xi}^{\mathrm{geo}}\bigr)^{q_d-1}$. Thus
\begin{equation*}
\|\mathbf A^{-1}\|_2 \le \|\mathbf A^{-1}\|_{\mathrm F}
=\frac{\|\operatorname{adj}\mathbf A\|_{\mathrm F}}{|\det\mathbf A|}
\le\frac{q_d^{(q_d+1)/2}\bigl(B_{\mathcal B,\Xi}^{\mathrm{geo}}\bigr)^{q_d-1}
}{\Delta_{\mathcal B,d,\Xi}^{\mathrm{geo}}}.
\end{equation*}
Applying this inverse bound to the sampled system gives
\begin{equation}\label{eq:cramer_geometric_coefficient_bound}
\|\mathbf c\|_{\ell^2} \le \frac{q_d^{(q_d+1)/2}
\bigl(B_{\mathcal B,\Xi}^{\mathrm{geo}}\bigr)^{q_d-1}
}{\Delta_{\mathcal B,d,\Xi}^{\mathrm{geo}}}
\left(\sum_{k=1}^{q_d}|(\mathcal T_{\mathcal B}G)(\rho_k\omega_k)|^2\right)^{1/2}.
\end{equation}
Combining \eqref{eq:geometric_coefficient_to_density_bound} and
\eqref{eq:cramer_geometric_coefficient_bound} proves
\eqref{eq:sampled_polygonal_stability}--\eqref{eq:explicit_determinant_stability_bound}.
The \(L^\infty(U)\) estimate follows by bounding the Euclidean norm of the
\(q_d\) samples by \(\sqrt{q_d}\) times their maximum.

\label{rem:polygonal_stability_degeneracy}
Suppose $0<\ell_*\le\ell_j\le\ell^*$, $0\le\beta_j\le\beta^*<\frac{\pi}{2}$,
and fix sampling pairs with $\Delta_{\mathcal B,d,\Xi}^{\mathrm{geo}}\ge\Delta_*>0$.
Then
\begin{equation*}
\ell_*\cos^2\beta^*\le |S_j(\rho,\omega)|,\quad
h^*\le\ell^*,\quad L_\theta\le N\ell^*,
\end{equation*}
and hence
\begin{equation*}
C_{\mathcal B,d,\Xi}^{\mathrm{geo}} \le \sqrt{\ell^*|D|M_d}\,
\frac{q_d^{(q_d+1)/2}\bigl(\ell^*|D|e^{\rho^*N\ell^*}\bigr)^{q_d-1}}{\Delta_*}.
\end{equation*}
The turning angles enter \(\Delta_*\) through
\eqref{eq:turning_angle_formula} and the vectors \(B_j\). A lower bound on
the turning angles alone is not enough: the base moments, sampling directions,
and oscillatory phase cancellations must also remain nondegenerate.

Finally,
\begin{equation*}
M_d=\binom{n-1+d}{d},\quad
q_d=N\binom{n-1+d}{d}
\sim \frac{N}{(n-1)!}d^{\,n-1}.
\end{equation*}
Thus \eqref{eq:explicit_determinant_stability_bound} shows the rapid
deterioration as the polynomial degree increases.

\label{lem:curve_interpolation}
The interpolant satisfies $\delta_N\le \omega_b(h_N)$, so \(\delta_N\to0\) as \(h_N\to0\). If \(b\in C^2([0,L];\theta^\perp)\), then
\begin{equation*}
\delta_N\le \frac18\|b''\|_{L^\infty(0,L)}h_N^2.
\end{equation*}

Fix \(t\in[t_{j-1},t_j]\) and write $t=(1-\lambda)t_{j-1}+\lambda t_j$, $0\le\lambda\le1$. Since \(b_N(t)=(1-\lambda)b(t_{j-1})+\lambda b(t_j)\),
\begin{equation*}
|b(t)-b_N(t)|\le (1-\lambda)|b(t)-b(t_{j-1})|+\lambda|b(t)-b(t_j)|
\le\omega_b(h_N).
\end{equation*}
Hence \(\delta_N\le\omega_b(h_N)\), and \(\delta_N\to0\) as \(h_N\to0\)
because \(b\) is uniformly continuous on \([0,L]\).

If \(b\in C^2\), the standard linear interpolation error bound on
\([t_{j-1},t_j]\) gives
\begin{equation*}
|b(t)-b_N(t)|\le\frac{(t_j-t_{j-1})^2}{8}\|b''\|_{L^\infty(t_{j-1},t_j)}.
\end{equation*}
Taking the maximum over all intervals yields
\begin{equation*}
\delta_N\le \frac18\|b''\|_{L^\infty(0,L)}h_N^2.
\end{equation*}

\label{lem:piecewise_polynomial_approximation}
There exist \(p_j\in\Pi_d(D)\) such that $P_{N,d}(y,t)=p_j(y)$, $t_{j-1}<t\le t_j$,
satisfies
\begin{equation*}
\|F-P_{N,d}\|_{L^\infty(D\times(0,L))}\le E_{N,d}(F),
\quad E_{N,d}(F)=\omega_{F,t}(h_N)+e_d(F).
\end{equation*}
Moreover,
\begin{equation*}
E_{N,d}(F)\to 0, \quad\text{as } h_N\to0,\ d\to\infty.
\end{equation*}

For each \(j\), choose \(t_j^*\in[t_{j-1},t_j]\). Since \(\Pi_d(D)\) is
finite-dimensional, a best approximant \(p_j\in\Pi_d(D)\) to
\(F(\cdot,t_j^*)\) exists, so
\begin{equation*}
\|F(\cdot,t_j^*)-p_j\|_{C(D)}\le e_d(F).
\end{equation*}
For \(t\in(t_{j-1},t_j]\),
\begin{equation*}
\|F(\cdot,t)-p_j\|_{C(D)}\le \|F(\cdot,t)-F(\cdot,t_j^*)\|_{C(D)}
+\|F(\cdot,t_j^*)-p_j\|_{C(D)}\le \omega_{F,t}(h_N)+e_d(F).
\end{equation*}
This proves the first assertion.

For the second, define
\begin{equation*}
a_d(t)=\inf_{p\in\Pi_d(D)}\|F(\cdot,t)-p\|_{C(D)}.
\end{equation*}
The map \(t\mapsto F(\cdot,t)\) is continuous into \(C(D)\), and the distance
to a fixed subspace is \(1\)-Lipschitz; hence each \(a_d\) is continuous. For
each fixed \(t\), Stone--Weierstrass gives \(a_d(t)\to0\). Since \([0,L]\) is
compact and \(a_d\) is continuous, Dini's theorem gives uniform convergence, so
\begin{equation*}
e_d(F)=\max_{t\in[0,L]}a_d(t)\to0.
\end{equation*}
Also \(\omega_{F,t}(h_N)\to0\) by uniform continuity of \(F\). Hence
\(E_{N,d}(F)\to0\).

\label{lem:curved_transform_model_error}
Let $M=\|F\|_{L^\infty(D\times(0,L))}$ and $E=E_{N,d}(F)$. Then, for every \(\eta\in\theta^\perp\) with \(\rho=|\eta|\),
\begin{equation}\label{eq:curved_transform_model_error}
\left|(\mathcal T_bF)(\eta)-(\mathcal T_{b_N}P_{N,d})(\eta)\right|
\le |D|J_L(\rho)\bigl[E+(M+E)\rho\delta_N\bigr].
\end{equation}

For each \((y,t)\),
\begin{equation*}
F e^{-i\eta\cdot b}
-
P_{N,d} e^{-i\eta\cdot b_N}
=
(F-P_{N,d})e^{-i\eta\cdot b}
+
P_{N,d}\bigl(e^{-i\eta\cdot b}-e^{-i\eta\cdot b_N}\bigr).
\end{equation*}
Since \(b,b_N\in\theta^\perp\), the exponential factors have modulus one,
and \(|e^{ia}-e^{ib}|\le |a-b|\) gives
\begin{equation*}
\bigl|e^{-i\eta\cdot b(t)}-e^{-i\eta\cdot b_N(t)}\bigr|
\le \rho\delta_N.
\end{equation*}
By Lemma~\ref{lem:piecewise_polynomial_approximation},
\(\|P_{N,d}\|_\infty\le M+E\). Multiplying by \(e^{\rho t}\) and integrating
over \(D\times(0,L)\), using \(\int_0^L e^{\rho t}\,dt=J_L(\rho)\), yields
\eqref{eq:curved_transform_model_error}.

\label{thm:curved_sweep_approximation_stability}
The reconstruction defined in (\ref{eq:model}) satisfies
\begin{equation}
\begin{aligned}\label{eq:curved_sweep_approximation_stability}
\|F-\widehat P_{N,d}\|_{L^2(D\times(0,L))}
\le (|D|L)^{1/2}E_{N,d}(F)+C_{\mathcal B_N,d,\Xi_{N,d}}^{\mathrm{geo}}
\left(\varepsilon+\mathcal M_{N,d,\Xi}\right).
\end{aligned}
\end{equation}

By the triangle inequality,
\begin{equation*}
\|F-\widehat P_{N,d}\|_{L^2}\le\|F-P_{N,d}\|_{L^2}+\|P_{N,d}-\widehat P_{N,d}\|_{L^2}.
\end{equation*}
Lemma~\ref{lem:piecewise_polynomial_approximation} gives
\begin{equation*}
\|F-P_{N,d}\|_{L^2(D\times(0,L))}\le (|D|L)^{1/2}E_{N,d}(F).
\end{equation*}
Since \(P_{N,d}\) and \(\widehat P_{N,d}\) lie in the same
finite-dimensional polygonal model,
Theorem~\ref{thm:polygonal_finite_dimensional_stability} yields
\begin{equation*}
\|P_{N,d}-\widehat P_{N,d}\|_{L^2} \le C_{\mathcal B_N,d,\Xi_{N,d}}^{\mathrm{geo}}
\|\mathcal T_{b_N}P_{N,d}-\mathbf d^\delta\|_{\ell^2}.
\end{equation*}
By Lemma~\ref{lem:curved_transform_model_error} and the noise assumption,
\begin{equation*}
\|\mathcal T_{b_N}P_{N,d}-\mathbf d^\delta\|_{\ell^2}
\le \|\mathcal T_{b_N}P_{N,d}-\mathcal T_bF\|_{\ell^2}+\|e\|_{\ell^2}
\le \mathcal M_{N,d,\Xi}+\varepsilon.
\end{equation*}
Combining these estimates proves
\eqref{eq:curved_sweep_approximation_stability}.

\label{lem:uniform_shifted_lattice_inverse}
Let \(1<p<\infty\). For \(\sigma=\pm1\), set $L_{\sigma,\xi}:=\Delta+2i\sigma \zeta_\theta(\xi)\cdot\nabla$. There exist right inverses $G_{\sigma,\xi}:L^p(Q)\to W^{2,p}(Q)$ such that
\begin{equation}\label{eq:right_inverse_equation}
L_{\sigma,\xi}G_{\sigma,\xi}F=F,\quad\text{in }Q,
\end{equation}
and
\begin{equation}\label{eq:shifted_inverse_estimate}
\|G_{\sigma,\xi}F\|_{W^{2,p}(Q)}\le C_{U,p}\|F\|_{L^p(Q)},
\quad\text{uniformly for }\xi\in U.
\end{equation}

Let \(\Delta_D^{-1}:L^p(Q)\to W^{2,p}(Q)\cap W_0^{1,p}(Q)\) be the Dirichlet
solution operator. The global \(W^{2,p}\) estimate gives
\begin{equation*}
\|\Delta_D^{-1}F\|_{W^{2,p}(Q)}\le C_{Q,p}\|F\|_{L^p(Q)}.
\end{equation*}
For \(\sigma=\pm1\), define
\begin{equation*}
G_{\sigma,\xi}F:=e^{-i\sigma \zeta_\theta(\xi)\cdot x}
\Delta_D^{-1}\bigl(e^{i\sigma \zeta_\theta(\xi)\cdot x}F\bigr).
\end{equation*}
Since \(\zeta_\theta(\xi)\cdot\zeta_\theta(\xi)=0\),
\begin{equation*}
(\Delta+2i\sigma \zeta_\theta(\xi)\cdot\nabla)
\bigl(e^{-i\sigma \zeta_\theta(\xi)\cdot x}v\bigr)
=e^{-i\sigma \zeta_\theta(\xi)\cdot x}\Delta v.
\end{equation*}
Hence \(L_{\sigma,\xi}G_{\sigma,\xi}F=F\). Multiplication by the exponentials
is uniformly bounded on \(L^p(Q)\) and \(W^{2,p}(Q)\) for \(\xi\in U\), so the
estimate follows from the Dirichlet bound.

\label{lem:hyperbolic_corrector}
Let \(q\in L^\infty(Q)\) with \(q\ge q_->0\), and let \(p_n\) satisfy
\eqref{eq:pn_condition}. There exist \(\tau_0>0\) and \(C_U>0\) such that,
for \(0<\tau<\tau_0\) and \(\xi\in U\), the equation
\begin{equation*}
\bigl(\Delta-2i\zeta_\theta(\xi)\cdot\nabla\bigr)\psi_{\tau,\xi}
=\tau^2 q(1+\psi_{\tau,\xi}), \quad\text{in }Q,
\end{equation*}
has a solution \(\psi_{\tau,\xi}\in W^{2,p_n}(Q)\) satisfying
\begin{equation}\label{eq:corrector_estimate}
\|\psi_{\tau,\xi}\|_{W^{2,p_n}(Q)}+\|\psi_{\tau,\xi}\|_{L^\infty(Q)}\le C_U\tau^2.
\end{equation}

By Lemma~\ref{lem:uniform_shifted_lattice_inverse}, solve the fixed-point
equation
\begin{equation*}
\psi=\mathcal T_{\tau,\xi}(\psi):=G_{-,\xi}\bigl[\tau^2q(1+\psi)\bigr],
\end{equation*}
in \(W^{2,p_n}(Q)\). Since \(2p_n>n\), we have
\(W^{2,p_n}(Q)\hookrightarrow L^\infty(Q)\), and therefore
\begin{equation*}
\|\mathcal T_{\tau,\xi}(\psi)\|_{W^{2,p_n}}
\le C_U\tau^2\|q(1+\psi)\|_{L^{p_n}}
\le C_U\tau^2\bigl(1+\|\psi\|_{W^{2,p_n}}\bigr),
\end{equation*}
while
\begin{equation*}
\|\mathcal T_{\tau,\xi}(\psi_1)-\mathcal T_{\tau,\xi}(\psi_2)\|_{W^{2,p_n}}
\le C_U\tau^2\|\psi_1-\psi_2\|_{W^{2,p_n}}.
\end{equation*}
Let \(C_0\) be a constant for which both estimates hold uniformly in
\(\xi\in U\). Choose \(\tau_0>0\) with \(2C_0\tau_0^2\le1\), and for
\(0<\tau<\tau_0\) set \(R_\tau=2C_0\tau^2\). If
\(\|\psi\|_{W^{2,p_n}}\le R_\tau\), then
\begin{equation*}
\|\mathcal T_{\tau,\xi}(\psi)\|_{W^{2,p_n}}
\le C_0\tau^2(1+R_\tau)\le 2C_0\tau^2 =R_\tau.
\end{equation*}
On this ball, \(\mathcal T_{\tau,\xi}\) is a contraction with Lipschitz
constant at most \(C_0\tau^2\le1/2\). Banach's fixed-point theorem gives a
unique fixed point, so
\begin{equation*}
\|\psi_{\tau,\xi}\|_{W^{2,p_n}}\le 2C_0\tau^2.
\end{equation*}
The Sobolev embedding, with a constant independent of \(\tau\) and \(\xi\),
yields \eqref{eq:corrector_estimate}. Only \(\|q\|_{L^\infty}\) is used, so a
jump of \(q\) across \(\partial\Omega_\sharp\) is allowed.

Define
\begin{equation*}
G(x):=q_1(x)f_1(x)-q_2(x)f_2(x)=\frac{f_1(x)}{c_1^2(x)}-\frac{f_2(x)}{c_2^2(x)}.
\end{equation*}
By \eqref{eq:hyperbolic_decoupled_complex_identity},
\begin{equation*}
\int_{\Omega_\sharp}G(x)e^{-ix\cdot\zeta_\theta(\xi)}\,dx=0, \quad \xi\in U.
\end{equation*}

If \(\Omega_\sharp=\Omega_{\theta,\mu,h}\), then the oblique cylinder quotient
structure \eqref{eq:main_hyperbolic_quotient_structure_translated} gives
\begin{equation*}
G(x)=G_0(y)\chi_{\Omega_{\theta,\mu,h}}(x),
\quad G_0:=F_1-F_2\in L^1(D).
\end{equation*}
Since \(\Omega_{\theta,\mu,h}\) is the interval case of
\(\Omega_{\theta,\mu,E}\) with \(E=(0,h)\),
Theorem~\ref{thm:main_totally_real_uniqueness} yields
\(G=0\) a.e. in \(\Omega_\sharp\).

If \(\Omega_\sharp=\Omega_{\mathcal B}=\bigcup_{j=1}^N P_j\), then the
polygonal cylinder quotient structure
\eqref{eq:main_hyperbolic_quotient_structure_broken} gives
\begin{equation*}
G(x)=\sum_{j=1}^N G_j(Y(x))\chi_{P_j}(x),
\quad G_j:=F_{1,j}-F_{2,j}\in\mathbb C[y_1,\dots,y_{n-1}].
\end{equation*}
Since the available phase is \(e^{-ix\cdot\zeta_\theta(\xi)}\),
Theorem~\ref{thm:main_brion_barvinok_uniqueness} gives
\(G_1=\cdots=G_N=0\), hence \(G=0\) a.e. in \(\Omega_\sharp\).

In both cases,
\begin{equation*}
\frac{f_1}{c_1^2}=\frac{f_2}{c_2^2}, \quad\text{a.e. }\mathbb R^n,
\end{equation*}
since both quotients vanish outside \(\overline{\Omega}_\sharp\).

Define
\begin{equation*}
G(x):=q_1(x)f_1(x)-q_2(x)f_2(x)=\frac{f_1(x)}{\kappa_1(x)}
-\frac{f_2(x)}{\kappa_2(x)}.
\end{equation*}
By \eqref{eq:para_decoupled_complex_identity},
\begin{equation*}
\int_{\Omega_\sharp}G(x)e^{-ix\cdot\zeta_\theta(\xi)}\,dx=0,
\quad \xi\in U.
\end{equation*}

If \(\Omega_\sharp=\Omega_{\theta,\mu,h}\), then the oblique cylinder quotient
structure \eqref{eq:main_parabolic_quotient_structure_translated} gives
\begin{equation*}
G(x)=G_0(y)\chi_{\Omega_{\theta,\mu,h}}(x),
\quad G_0:=F_1-F_2\in L^1(D).
\end{equation*}
Applying Theorem~\ref{thm:main_totally_real_uniqueness} to the oblique cylinder
case \(E=(0,h)\), we get \(G=0\) a.e. \(\Omega_\sharp\).

If \(\Omega_\sharp=\Omega_{\mathcal B}=\bigcup_{j=1}^N P_j\), then the
polygonal cylinder quotient structure
\eqref{eq:main_parabolic_quotient_structure_broken} gives
\begin{equation*}
G(x)=\sum_{j=1}^N G_j(Y(x))\chi_{P_j}(x),
\quad G_j:=F_{1,j}-F_{2,j}\in\mathbb C[y_1,\dots,y_{n-1}].
\end{equation*}
Theorem~\ref{thm:main_brion_barvinok_uniqueness} applies to the same phase
\(e^{-ix\cdot\zeta_\theta(\xi)}\). Hence \(G_j=0\) for all \(j\), and
\(G=0\) a.e. \(\Omega_\sharp\).

In both cases,
\begin{equation*}
\frac{f_1}{\kappa_1}=\frac{f_2}{\kappa_2}, \quad\text{a.e. }\mathbb R^n,
\end{equation*}
since both quotients vanish outside \(\overline{\Omega}_\sharp\).

\label{lem:finite_time_endpoint_identity}
For each \(\iota=1,2\), let $\mathcal{M}_{\iota,k}^{T} := \mathcal{G}_{W_{\iota,k}^{T}}$ \(\in \mathfrak{T}(\Omega_\sharp)^{*}\), then
\begin{equation}\label{eq:finite_time_boundary_extension}
\mathcal{M}_{\iota,k}^{T} \longrightarrow \mathcal{M}_{\iota}^{T},
\quad\text{in } \mathfrak{T}(\Omega_\sharp)^{*},
\end{equation}
and the limit is independent of the approximating sequence. Hence
\(\mathcal{M}_{\iota}^{T}\) is the unique continuous extension of the
weighted weak-Cauchy-trace functional from \(D(A_{q_\iota})\) to
\(L^{2}(\mathbb{R}^{n})\).

Moreover, for \(v \in \mathcal{H}(\Omega_\sharp)\) and generalized
finite-time boundary data as in
Subsection~\ref{subsec:main_finite_time}, both the wave and heat
equations satisfy
\begin{equation}\label{eq:finite_time_endpoint_identity}
\int_{\Omega_\sharp} G v \, dx=\int_{\Omega_\sharp} R_T v \, dx- \mathfrak{D}_T(v).
\end{equation}
If \(\mathcal{M}_{1}^{T} = \mathcal{M}_{2}^{T}\), then
\begin{equation*}
\left| \int_{\Omega_\sharp} G v \, dx \right|
\le \varepsilon_T \, \|v\|_{L^{2}(\Omega_\sharp)}.
\end{equation*}

Fix \(v\in\mathcal H(\Omega_\sharp)\). Recall the definition of \(W_\iota^T\) in (\ref{eq:WjT}); the Bochner integral lies in \(L^2(\Omega_\sharp)\).

For \(\iota=1,2\), choose \(f_{\iota,k}\in\mathcal D(A_{q_\iota})\) with
\begin{equation*}
f_{\iota,k}\longrightarrow f_\iota, \quad\text{in }L^2(\mathbb R^n),
\end{equation*}
and let {\(u_{\iota,k}\)} be the corresponding strong solution. Since {\(q_\iota\)}
is bounded above and below by positive constants, the weighted and
unweighted \(L^2\)-norms are equivalent.

\medskip
\noindent\emph{Case 1. Wave equation.}
By the spectral theorem,
\begin{equation*}
{\sup_{0\le t\le T}\|u_{\iota,k}(t)-u_\iota(t)\|_{L^2(\mathbb R^n)}
\le \|f_{\iota,k}-f_\iota\|_{L^2(\mathbb R^n)}},
\end{equation*}
hence
\begin{equation*}
{\|W_{\iota,k}^T-W_\iota^T\|_{L^2(\Omega_\sharp)}
\le \frac{T^2}{2} \sup_{0\le t\le T} \|u_{\iota,k}(t)-u_\iota(t)\|_{L^2(\Omega_\sharp)}}
\longrightarrow 0.
\end{equation*}
For the strong solution, spatial testing and two integrations in time give
\begin{equation*}
{\int_0^T(T-t)\partial_t^2u_{\iota,k}(t)\,dt
=\bigl[(T-t)\partial_tu_{\iota,k}(t)\bigr]_{0}^{T}+\int_0^T\partial_tu_{\iota,k}(t)\,dt
=u_{\iota,k}(T)-f_{\iota,k}},
\end{equation*}
since {\(\partial_tu_{\iota,k}(0)=0\)}. Therefore
\begin{equation*}
{\Delta W_{\iota,k}^T=q_\iota\bigl(u_{\iota,k}(T)-f_{\iota,k}\bigr)},
\end{equation*}
and the contraction estimate at \(t=T\) yields
\begin{equation*}
{\|\Delta W_{\iota,k}^T-q_\iota(u_\iota(T)-f_\iota)\|_{L^2(\Omega_\sharp)}
\le \|q_\iota\|_{L^\infty(\Omega_\sharp)}\Big(\|u_{\iota,k}(T)-u_\iota(T)\|_{L^2(\Omega_\sharp)}
+\|f_{\iota,k}-f_\iota\|_{L^2(\Omega_\sharp)}\Big)}\longrightarrow0.
\end{equation*}

\noindent\emph{Case 2. Heat equation.}
The semigroup contraction gives the same uniform convergence of
{\(u_{\iota,k}\) to \(u_\iota\)} on \([0,T]\). By the definitions of {\(W_{\iota,k}^T\)}
and {\(W_\iota^T\)},
\begin{equation*}
{\|W_{\iota,k}^T-W_\iota^T\|_{L^2(\Omega_\sharp)}
\le T\sup_{0\le t\le T} \|u_{\iota,k}(t)-u_\iota(t)\|_{L^2(\Omega_\sharp)}} \longrightarrow0,
\end{equation*}
and a single integration in time gives
\begin{equation*}
{\Delta W_{\iota,k}^T =q_\iota\int_0^T\partial_tu_{\iota,k}(t)\,dt=q_\iota\bigl(u_{\iota,k}(T)-f_{\iota,k}\bigr)},
\end{equation*}
so the semigroup contraction and the norm equivalence imply
\begin{equation*}
{\Delta W_{\iota,k}^T\longrightarrow q_\iota\bigl(u_\iota(T)-f_\iota\bigr)},
\quad\text{in }L^2(\Omega_\sharp).
\end{equation*}

In either model, the convergence of {\(W_{\iota,k}^T\)} and its Laplacian
gives
\begin{equation*}
{W_\iota^T\in H_\Delta(\Omega_\sharp),\quad \Delta W_\iota^T=q_\iota\bigl(u_\iota(T)-f_\iota\bigr),
\quad W_{\iota,k}^T\longrightarrow W_\iota^T},\quad \text{in }H_\Delta(\Omega_\sharp).
\end{equation*}
Indeed, the distributional identity for the limit follows by testing
against \(C_c^\infty(\Omega_\sharp)\) and passing to the limit in both
\(L^2\)-convergences.

Define {\(\mathcal M_{\iota,k}^T:=\mathcal G_{W_{\iota,k}^T}\)}. The continuity
estimate from Subsection~\ref{subsec:main_finite_time} gives
\begin{equation*}
{\|\mathcal M_{\iota,k}^T-\mathcal M_\iota^T\|_{\mathfrak T(\Omega_\sharp)^*}
\le C_n\bigl(\|W_{\iota,k}^T-W_\iota^T\|_{L^2(\Omega_\sharp)}
+\|\Delta W_{\iota,k}^T-\Delta W_\iota^T\|_{L^2(\Omega_\sharp)}\bigr)}\longrightarrow0,
\end{equation*}
with \(C_n\) independent of {\(\iota\)}, \(k\), and \(T\).

The same estimates bound the extension. Fix a coefficient \(q\) and set
\begin{equation*}
q_-:=\operatorname*{ess\,inf}_{\mathbb R^n}q>0,
\quad b_T:=
\begin{cases}
T^2/2, & \text{wave equation},\\
T, & \text{heat equation}.
\end{cases}
\end{equation*}
For \(f\in\mathcal D(A_q)\), the contraction estimates and the identity
\(\Delta W_f^T=q(u_f(T)-f)\) give
\begin{eqnarray*}
\|W_f^T\|_{L^2(\Omega_\sharp)}
&\le& b_T\,q_-^{-1/2}\|f\|_{L^2(\mathbb R^n)},\\
\|\Delta W_f^T\|_{L^2(\Omega_\sharp)}
&\le& 2\|q\|_{L^\infty(\mathbb R^n)}q_-^{-1/2}\|f\|_{L^2(\mathbb R^n)}.
\end{eqnarray*}
Consequently,
\begin{equation*}
\|\mathcal M_f^T\|_{\mathfrak T(\Omega_\sharp)^*}
\le C_n q_-^{-1/2}\bigl(b_T+2\|q\|_{L^\infty(\mathbb R^n)}\bigr)
\|f\|_{L^2(\mathbb R^n,q\,dx)}.
\end{equation*}
Thus, for each fixed \(T>0\), the map \(f\mapsto\mathcal M_f^T\) extends
uniquely and continuously from \(\mathcal D(A_q)\) to
\(L^2(\mathbb R^n,q\,dx)\).

For every \(k\), the strong solution lies in
{\(C([0,T];\mathcal D(A_{q_\iota}))\)}, and the graph norm on
{\(\mathcal D(A_{q_\iota})\)} is equivalent to the \(H^2(\mathbb R^n)\)-norm.
Hence its weak Dirichlet and Neumann traces are continuous in time in
\(H^{1/2}(\partial\Omega_\sharp)\) and
\(H^{-1/2}(\partial\Omega_\sharp)\), respectively. Since the bounded
trace maps commute with the \(H^2\)-valued Bochner integral, the weak
second Green identity and time integration give
\begin{eqnarray*}
{\mathcal M_{\iota,k}^T([\phi])}
=\int_0^T a_T(t)\Big(\langle\gamma_N{u_{\iota,k}}(t),\gamma_D\phi\rangle_{-1/2,1/2}
-\langle\gamma_N\phi,\gamma_D{u_{\iota,k}}(t)\rangle_{-1/2,1/2}\Big)\,dt.
\end{eqnarray*}
Thus the weighted weak Cauchy traces of the strong solutions determine
{\(\mathcal M_{\iota,k}^T\)}, and the convergence in
\(\mathfrak T(\Omega_\sharp)^*\) shows that {\(\mathcal M_\iota^T\)} is their
continuous extension. The limit is independent of the approximating
sequence, since it equals {\(\mathcal G_{W_\iota^T}\)}. This conclusion does
not assign pointwise-in-time Cauchy traces to the mild solution.

Now take the harmonic test function \(v\). Since \(\Delta v=0\), the
definition of {\(\mathcal M_\iota^T\)} and the terminal identity give
\begin{equation*}
{\mathcal M_\iota^T([v])=\int_{\Omega_\sharp}q_\iota\bigl(u_\iota(T)-f_\iota\bigr)v\,dx.}
\end{equation*}
Subtracting the identities for {\(\iota=1\)} and {\(\iota=2\)}, and using the
definitions of \(G\), \(R_T\), and \(\mathfrak D_T\), we get
\begin{equation*}
\mathfrak D_T(v)=\int_{\Omega_\sharp}(R_T-G)v\,dx,
\end{equation*}
which is equivalent to \eqref{eq:finite_time_endpoint_identity}.

If \(\mathcal M_1^T=\mathcal M_2^T\), then \(\mathfrak D_T(v)=0\), so
\begin{equation*}
\left|\int_{\Omega_\sharp}Gv\,dx\right|=\left|\int_{\Omega_\sharp}R_Tv\,dx\right|
\le \|R_T\|_{L^2(\Omega_\sharp)}\|v\|_{L^2(\Omega_\sharp)}
=\varepsilon_T\|v\|_{L^2(\Omega_\sharp)}.
\end{equation*}
This completes the proof.

\label{lem:shear_adapted_null_phase}
The vector \(\zeta_\mu(\eta)\) satisfies $\zeta_\mu(\eta)\cdot\zeta_\mu(\eta)=0$.
Moreover, if $x=x_0+y+(\mu\cdot y+r)\theta$, $y\in D$, $0<r<h$, then
\begin{equation*}
e^{-i(x-x_0)\cdot\zeta_\mu(\eta)}=e^{-i\eta\cdot y}e^{-i\beta_\mu(\eta)r}.
\end{equation*}

Write \(\zeta=\zeta_\mu(\eta)\), \(\alpha=\alpha_\mu(\eta)\), and
\(\beta=\beta_\mu(\eta)\). Since \(\alpha,\mu,\eta\in\theta^\perp\)
and \(\theta\cdot\theta=1\),
\begin{equation*}
\zeta\cdot\zeta=|\alpha|^2+\beta^2=|\eta-\beta\mu|^2+\beta^2
=|\eta|^2-2\beta(\mu\cdot\eta)+(1+|\mu|^2)\beta^2.
\end{equation*}
The last expression vanishes because \(\beta\) solves
\begin{equation*}
(1+|\mu|^2)\beta^2-2(\mu\cdot\eta)\beta+|\eta|^2=0.
\end{equation*}
Hence \(\zeta\cdot\zeta=0\). Also, since \(\alpha+\beta\mu=\eta\),
\begin{equation*}
(x-x_0)\cdot\zeta=y\cdot\alpha+(\mu\cdot y+r)\beta=y\cdot\eta+r\beta.
\end{equation*}
Exponentiating gives the claimed factorization.

\label{lem:finite_time_fourier_bound}
Let \(G(x)=G_0(y)\chi_{\Omega_{\theta,\mu,h}}(x)\), where \(G_0\in L^2(D)\),
and let \(\widetilde{G}_0\) denote its extension by zero outside \(D\). Then
\begin{equation*}
|\widehat{\widetilde{G}}_0(\eta)|
\le C_{D,\mu,h}\,\varepsilon_T\,\langle\eta\rangle^{1/2}, \quad 
\eta\in\mathbb R^{n-1}.
\end{equation*}

For \(\eta\ne0\), set
\begin{equation*}
v_\eta(x)=e^{-i(x-x_0)\cdot\zeta_\mu(\eta)},
\quad \beta=\beta_\mu(\eta),
\quad b=b_\mu(\eta)=\frac{\chi_\mu(\eta)}{1+|\mu|^2}>0.
\end{equation*}
By Lemma~\ref{lem:shear_adapted_null_phase}, \(\Delta v_\eta=0\). Inserting
\(v_\eta\) into Lemma~\ref{lem:finite_time_endpoint_identity} and using the
unit Jacobian of \((y,r)\), we obtain
\begin{equation*}
B_h(\beta)\widehat{\widetilde{G}}_0(\eta)
=\int_{\Omega_{\theta,\mu,h}}R_T(x)v_\eta(x)\,dx,
\quad B_h(\beta)=\int_0^h e^{-i\beta r}\,dr.
\end{equation*}
Since
\begin{equation*}
|B_h(\beta)|=\left|\frac{e^{-i\beta h}-1}{-i\beta}\right|
\ge \frac{e^{bh}-1}{|\beta|}>0,
\end{equation*}
and
\begin{equation*}
\|v_\eta\|_{L^2(\Omega_{\theta,\mu,h})}^2
=|D|\int_0^h e^{2br}\,dr=|D|\frac{e^{2bh}-1}{2b},\quad b>0,
\end{equation*}
we have
\begin{equation*}
\frac{\|v_\eta\|_{L^2}^2}{|B_h(\beta)|^2}
\le|D|\frac{|\beta|^2}{2b}\coth\left(\frac{bh}{2}\right).
\end{equation*}
A direct calculation gives
\begin{equation*}
|\beta|^2=\frac{|\eta|^2}{1+|\mu|^2},\quad c_\mu|\eta|\le b\le C_\mu|\eta|,
\end{equation*}
for some constants \(c_\mu,C_\mu>0\). Since \(\coth s\le1+s^{-1}\) for
\(s>0\), it follows that
\begin{equation*}
\frac{\|v_\eta\|_{L^2}}{|B_h(\beta)|}\le C_{D,\mu,h}\langle\eta\rangle^{1/2}.
\end{equation*}
The Cauchy--Schwarz estimate in Lemma~\ref{lem:finite_time_endpoint_identity}
now proves the claim for \(\eta\ne0\).

Finally, since \(|D|<\infty\),
\begin{equation*}
\|G_0\|_{L^1(D)} \le |D|^{1/2}\|G_0\|_{L^2(D)},
\end{equation*}
so the zero extension \(\widetilde G_0\) lies in \(L^1(\mathbb R^{n-1})\)
and its Fourier transform is continuous. Letting \(\eta\to0\) in the estimate
for \(\eta\ne0\) gives the same bound at \(\eta=0\).

For \(1\le k\le q_d\), set $v_k(x)=e^{-i(x-x_0)\cdot\zeta_\theta(\rho_k\omega_k)}$. Since \(\zeta_\theta\) is null, \(\Delta v_k=0\). By
Lemma~\ref{lem:finite_time_endpoint_identity} and the definition of the
normalized transform,
\begin{equation*}
(\mathcal T_{\mathcal B}G)(\rho_k\omega_k)=\int_{\Omega_{\mathcal B}}R_T(x)v_k(x)\,dx.
\end{equation*}
Cauchy--Schwarz gives
\begin{equation*}
|(\mathcal T_{\mathcal B}G)(\rho_k\omega_k)|
\le\varepsilon_T\|v_k\|_{L^2(\Omega_{\mathcal B})}.
\end{equation*}
Squaring and summing over \(k\), Theorem~\ref{thm:polygonal_finite_dimensional_stability}
yields
\begin{equation*}
\|G\|_{L^2(\Omega_{\mathcal B})} \le C_{\mathcal B,d,\Xi}^{\mathrm{geo}}
K_{\mathcal B,\Xi}\varepsilon_T.
\end{equation*}
This proves \eqref{eq:main_finite_time_polygonal}.
